mapper.select:
SELECT COUNT(*) FROM genomic_consents
 WHERE 1=1
 AND tenant_id = #{tenantId}
 AND patient_id = #{patientId}
 AND status = #{status}

mapper.update:
UPDATE genomic_consents
   SET status = 'SIGNED', signed_at = NOW(), signed_by_name = #{signedByName},
       witness_name = #{witnessName}, updated_at = NOW()
 WHERE consent_id = #{consentId}
 AND tenant_id = #{tenantId}
   AND status = 'PENDING'

UPDATE genomic_consents
   SET status = 'REVOKED', revoked_at = NOW(), updated_at = NOW()
 WHERE consent_id = #{consentId}
 AND tenant_id = #{tenantId}
   AND status = 'SIGNED'
